import { q } from "./q";

/** One delivery per logical SaaS event (earliest received), filtered first: retries share event_id, event_name and occurred_at. */
const logical = (where: string) => `SELECT * FROM (SELECT e.*, ROW_NUMBER() OVER (PARTITION BY event_id ORDER BY received_at, delivery_id) AS copy FROM events e WHERE ${where}) WHERE copy = 1`;
const CHECKOUT_RULES = [
  "Every stage starts from the original tables; recompute what you need.",
  "Use one delivery per event_id: the earliest received_at, ties by the lowest delivery_id.",
  "Times are UTC. The checkout window is checkout_started at or after pricing_viewed, then subscription_started for the same workspace within 24 hours after checkout.",
];
const CASE = (stage: number) => ({ id: "harbor-checkout-review", title: "Product: self-serve upgrade review", stage, total: 5 });
/** Bank statement lines exported as text by a partner bank. */
const STATEMENT_IMPORT = `CREATE TABLE statement_import (line_id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL, amount_text TEXT);
INSERT INTO statement_import SELECT transaction_id, account_id, CASE transaction_id % 6 WHEN 0 THEN printf('$%,.2f', amount_cents / 100.0) WHEN 1 THEN printf('%.2f', amount_cents / 100.0) WHEN 2 THEN CASE WHEN amount_cents < 0 THEN printf('(%.2f)', -amount_cents / 100.0) ELSE printf('%.2f', amount_cents / 100.0) END WHEN 3 THEN printf(' %.2f ', amount_cents / 100.0) WHEN 4 THEN printf('%.1f', amount_cents / 100.0) ELSE printf('USD %.2f', amount_cents / 100.0) END FROM transactions WHERE status = 'posted' AND account_id BETWEEN 1 AND 40 AND transaction_type <> 'interest';`;
/** A partner feed of external ledger references, replayed with duplicates. */
const LEDGER_FEED = `CREATE TABLE partner_feed (external_ref TEXT NOT NULL, account_id INTEGER NOT NULL, amount_cents INTEGER NOT NULL, posted_at TEXT NOT NULL);
INSERT INTO partner_feed SELECT 'EXT-' || transaction_id, account_id, amount_cents, posted_at FROM transactions WHERE transaction_type = 'payroll' AND account_id <= 60;
INSERT INTO partner_feed SELECT * FROM partner_feed WHERE CAST(substr(external_ref, 5) AS INTEGER) % 7 = 0;
CREATE TABLE partner_ledger (external_ref TEXT PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(account_id), amount_cents INTEGER NOT NULL, posted_at TEXT NOT NULL);`;

