    difficulty: "hard", difficultyWhy: "Collapse consecutive equal values into intervals.", primaryTopic: "warehousing.history", topicTags: ["windows.gaps-islands"],
    objective: "Turn event snapshots into validity intervals.", prerequisites: [78, 24],
    task: "Find identified customers whose invoices list more than one country. Return customer_id, country, valid_from and valid_to: one row per run of consecutive invoices (by ordered_at, order_id) with the same country. valid_from is the run’s first invoice date; valid_to is the next run’s first invoice date, NULL for the last run.",
