    hints: ["Mark a new run when the country differs from the previous invoice’s country (LAG).", "Running SUM of the marks numbers the runs; then LEAD the run start."],
    solution: "WITH multi AS (SELECT customer_id FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id HAVING COUNT(DISTINCT country) > 1), marked AS (SELECT o.customer_id, o.country, date(o.ordered_at) AS d, o.ordered_at, o.order_id, CASE WHEN LAG(o.country) OVER (PARTITION BY o.customer_id ORDER BY o.ordered_at, o.order_id) = o.country THEN 0 ELSE 1 END AS new_run FROM orders o JOIN multi USING (customer_id)), runs AS (SELECT customer_id, country, d, SUM(new_run) OVER (PARTITION BY customer_id ORDER BY ordered_at, order_id) AS run FROM marked), starts AS (SELECT customer_id, run, country, MIN(d) AS valid_from FROM runs GROUP BY customer_id, run, country) SELECT customer_id, country, valid_from, LEAD(valid_from) OVER (PARTITION BY customer_id ORDER BY run) AS valid_to FROM starts",
