    hints: ["Aggregate refunds and credited chargebacks per settlement separately.", "COALESCE missing sums to 0 before comparing."],
    solution: "WITH r AS (SELECT settlement_id, SUM(amount_cents) AS cents FROM refunds GROUP BY settlement_id), c AS (SELECT settlement_id, SUM(amount_cents) AS cents FROM chargebacks WHERE status = 'credited' GROUP BY settlement_id) SELECT s.settlement_id, s.amount_cents AS settled_cents, COALESCE(r.cents, 0) AS refunded_cents, COALESCE(c.cents, 0) AS disputed_cents, CASE WHEN COALESCE(r.cents, 0) + COALESCE(c.cents, 0) > s.amount_cents THEN 'double_recovery' WHEN COALESCE(r.cents, 0) + COALESCE(c.cents, 0) = s.amount_cents THEN 'fully_recovered' ELSE 'partially_recovered' END AS status FROM settlements s LEFT JOIN r ON r.settlement_id = s.settlement_id LEFT JOIN c ON c.settlement_id = s.settlement_id WHERE s.settled_at >= '2025-01-01' AND s.settled_at < '2025-04-01' AND (r.cents IS NOT NULL OR c.cents IS NOT NULL)",
